-- Temporales (plan de fusión, Luciano et al., 2009): transformación de funciones como última fase.
-- Vincular Mutuamente: umbral de tiempo («Se hace de noche justo cuando Pim termina de saltar.
-- ¿Qué hace Pim de noche?»), A → B y B → A.
-- Redes: «Ahora hazlo tú como Pim: toca las tres acciones en el orden en que las hace» (respuesta
-- de ordenar en la tableta; respuesta esperada por fase). Se retira «Transferir Funciones a través
-- de Relaciones Temporales» (su prueba con acciones reales pasa a fuera de la tableta).
begin;
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "Pim salta antes de cantar. ¿Qué hace Pim después de saltar?", "entrenamiento:B→A": "Pim salta antes de cantar. ¿Qué hace Pim antes de cantar?", "transformacion_funciones:A→B": "Pim salta antes de cantar. Se hace de noche justo cuando Pim termina de saltar. ¿Qué hace Pim de noche?", "transformacion_funciones:B→A": "Pim salta antes de cantar. Se hace de día justo cuando Pim empieza a cantar. ¿Qué hace Pim todavía de noche?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Temporales' and c.nombre = 'Clase 1';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:A→B', $j$Pim salta antes de cantar. Se hace de noche justo cuando Pim termina de saltar. ¿Qué hace Pim de noche?$j$, 'transformacion_funciones:B→A', $j$Pim salta antes de cantar. Se hace de día justo cuando Pim empieza a cantar. ¿Qué hace Pim todavía de noche?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Temporales' and c.nombre = 'Clase 1';
