update programas_base set secuencia_rft = '[{"fase": "entrenamiento", "origen": "B", "destino": "A"}, {"fase": "test_mutuo", "origen": "A", "destino": "B"}, {"fase": "transformacion_funciones", "origen": "A", "destino": "B"}, {"fase": "transformacion_funciones", "origen": "B", "destino": "A"}]'::jsonb,
  objetivo = objetivo || $t$ Además, transforma una función a través de la relación («Se hace de noche justo cuando Pim termina de saltar. ¿Qué hace Pim de noche?» → canta).$t$,
  instrucciones_terapeuta = regexp_replace(regexp_replace(instrucciones_terapeuta, E'\n(Generalización \\(sondas\\):)', $t$
Fase 3 - Test de Transformación de Funciones a través de la relación mutua, sin entrenamiento directo (Luciano et al., 2009):

1. Enuncie la relación y un momento que la divide justo por una de las dos acciones, y pregunte por la otra: "Pim salta antes de cantar. Se hace de noche justo cuando Pim termina de saltar. ¿Qué hace Pim de noche?" (respuesta: canta). Con el umbral en la otra acción: "… Se hace de día justo cuando Pim empieza a cantar. ¿Qué hace Pim todavía de noche?" (respuesta: salta).
2. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta.
3. Elegir la acción que nombra la frase del umbral indica que no transforma la función a través de la relación.

\1$t$), E'(- Test de vínculo mutuo:[^\n]*\n)', $t$\1- Transformación de funciones: A → B (umbral en A: "Se hace de noche justo cuando Pim termina de saltar. ¿Qué hace Pim de noche?"; la respuesta es B) y B → A (umbral en B; la respuesta es A)
$t$)
where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones Temporales' and instrucciones_terapeuta not like '%Fase 3 - Test de Transformación de Funciones a través de la relación mutua%';
update programas_alumno pa set objetivo = pb.objetivo, secuencia_rft = pb.secuencia_rft, respuesta_por_fase = pb.respuesta_por_fase, instrucciones_terapeuta = pb.instrucciones_terapeuta
from programas_base pb where pa.programa_base_id = pb.id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Temporales';

update programas_base set secuencia_rft = '[{"fase": "entrenamiento", "origen": "B", "destino": "A"}, {"fase": "entrenamiento", "origen": "C", "destino": "B"}, {"fase": "test_mutuo", "origen": "A", "destino": "B"}, {"fase": "test_mutuo", "origen": "B", "destino": "C"}, {"fase": "test_combinatorio", "origen": "C", "destino": "A"}, {"fase": "test_combinatorio", "origen": "A", "destino": "C"}, {"fase": "transformacion_funciones", "origen": "A", "destino": "C"}]'::jsonb, respuesta_por_fase = '{"transformacion_funciones": {"tipo": "orden", "opciones": []}}'::jsonb,
  objetivo = objetivo || $t$ Además, actúa según la red: toca las tres acciones en el orden en que las hace el personaje.$t$,
  instrucciones_terapeuta = regexp_replace(regexp_replace(instrucciones_terapeuta, E'\n(Generalización \\(sondas\\):)', $t$
Fase 4 - Test de Transformación de Funciones a través de la red, sin entrenamiento directo (Luciano et al., 2009):

1. Diga las dos premisas y pida que actúe según la red: "Pim recorta antes de leer. Pim lee antes de abrazar. Ahora hazlo tú como Pim: toca las tres acciones en el orden en que las hace Pim." En la tableta, el alumno toca las tres acciones en orden (salen numeradas); es correcto solo si el orden completo lo es.
2. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta (la tableta guarda el orden que ha tocado).
3. Tocar las acciones en el orden en que se nombran (y no en el que ocurren) indica que responde por el orden de las palabras.
4. Fuera de la tableta (sin registro): que haga las tres acciones de verdad, en el orden que indica la red.

\1$t$), E'(- Test de vínculo combinatorio:[^\n]*\n)', $t$\1- Transformación de funciones: A → C (ordenar: "Ahora hazlo tú como Pim: toca las tres acciones en el orden en que las hace Pim"; se registra el orden tocado)
$t$)
where clinica_id is null and nombre = 'Derivar Relaciones Temporales en Redes Combinatorias' and instrucciones_terapeuta not like '%Fase 4 - Test de Transformación de Funciones a través de la red%';
update programas_alumno pa set objetivo = pb.objetivo, secuencia_rft = pb.secuencia_rft, respuesta_por_fase = pb.respuesta_por_fase, instrucciones_terapeuta = pb.instrucciones_terapeuta
from programas_base pb where pa.programa_base_id = pb.id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones Temporales en Redes Combinatorias';

update programas_base set instrucciones_terapeuta = replace(instrucciones_terapeuta, 'Fuera de la tableta (sin registro): use las mismas relaciones', 'Fuera de la tableta (sin registro): instrucciones con el orden de las palabras inverso al de las acciones ("Salta después de tocar la mesa": primero tocar la mesa); use también las mismas relaciones')
where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones Temporales';
update programas_alumno pa set instrucciones_terapeuta = pb.instrucciones_terapeuta from programas_base pb where pa.programa_base_id = pb.id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Temporales';

update programas_base set activo = false, orden = null where clinica_id is null and nombre = 'Transferir Funciones a través de Relaciones Temporales';

commit;
